// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

import {ArchAdapterPresale} from "./ArchAdapterPresale.sol";

/// @title ArchAdapterPresaleDeployer
/// @notice Isolates presale creation bytecode from the versioned launchpad.
///         The deployer can be bound to exactly one launchpad.
contract ArchAdapterPresaleDeployer {
    address public immutable ADMIN;
    address public launchpad;

    constructor() {
        ADMIN = msg.sender;
    }

    function setLaunchpad(address launchpad_) external {
        require(msg.sender == ADMIN && launchpad == address(0) && launchpad_ != address(0), "adapter deployer: auth");
        require(launchpad_.code.length > 0, "adapter deployer: invalid launchpad");
        launchpad = launchpad_;
    }

    function deploy(
        address creator,
        ArchAdapterPresale.Infra calldata infra,
        ArchAdapterPresale.TokenConfig calldata tokenConfig,
        ArchAdapterPresale.SaleConfig calldata saleConfig
    ) external returns (address) {
        require(msg.sender == launchpad, "adapter deployer: only launchpad");
        return address(new ArchAdapterPresale(creator, infra, tokenConfig, saleConfig));
    }
}

src/interfaces/IArchLaunchLiquidityAdapt.content:
// SPDX-License-Identifier: LicenseRef-ArchLiquid-Proprietary
pragma solidity 0.8.30;

interface IArchLaunchRegistry {
    function isLaunch(address candidate) external view returns (bool);
}

/// @title IArchLaunchLiquidityAdapter
/// @notice AMM-family boundary used by versioned ArchLiquid launch contracts.
///         The caller transfers an exact token/WETH seed into a canonical pool;
///         the adapter then either time-locks or permanently custodies the LP
///         position and returns enough identity data to wire the launch token.
interface IArchLaunchLiquidityAdapter {
    struct SeedParams {
        address token;
        uint256 tokenAmount;
        uint256 wethAmount;
        address lockOwner;
        uint64 unlockTime;
        bool permanent;
    }

    struct SeedResult {
        address market;
        bytes32 poolId;
        address positionManager;
        uint256 positionIdOrAmount;
        uint256 lockId;
        uint256 tokenUsed;
        uint256 wethUsed;
    }

    function weth() external view returns (address);
    function liquidityProvisioner() external view returns (address);
    function validateSeedAmounts(uint256 tokenAmount, uint256 wethAmount) external view;
    function seed(SeedParams calldata params) external returns (SeedResult memory result);
}

